use mip_codex::{mps,row_ray,row_subgradient,solve::Result};
use std::time::{Instant,Duration};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let initial=row_ray::compute(&m,Instant::now()+Duration::from_secs(1)).unwrap();let target=m.offset+m.variables.iter().map(|v|v.objective.max(0.)).sum::<f64>();let proof=row_subgradient::compute(&m,target,Some(&initial),Instant::now()+Duration::from_millis(20));let bound=proof.as_ref().map_or(initial.normalized_bound,|p|p.normalized_bound.max(initial.normalized_bound));let r=Result{status:"diagnostic_bounds_only".into(),dual_bound:Some(bound),row_ray_proof:Some(initial),row_subgradient_proof:proof,..Result::default()};serde_json::to_writer(std::io::stdout(),&r).unwrap();}
